text:
{
  "claims": [
    {
      "text": "NVIDIA expanded the Cosmos platform with new training tools, simulation checkpoints, and Cosmos Data Factory blueprints in October 2026.",
      "kind": "date",
      "status": "unverified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "The source excerpt confirms the expansion of the platform but does not mention the date October 2026."
    },
    {
      "text": "The NVIDIA Cosmos platform ranks in the top five on six different open models leaderboards",
      "kind": "other",
      "status": "verified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Directly supported by excerpt E2."
    },
    {
      "text": "NVIDIA expanded the Cosmos platform to help physical AI systems understand and simulate the real world",
      "kind": "other",
      "status": "verified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Supported by excerpt E3."
    },
    {
      "text": "Cosmos 3 Nano model variants for simulation enable developers to test autonomous policies in repeatable scenarios",
      "kind": "other",
      "status": "verified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Supported by excerpt E4."
    },
    {
      "text": "Cosmos Data Factory blueprints include Event Video Generation, which turns still images into synthetic videos of rare or unsafe events",
      "kind": "other",
      "status": "verified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Supported by excerpt E5."
    },
    {
      "text": "Cosmos NIM microservices deliver up to 2x faster inference with no quality loss in validated configurations",
      "kind": "number",
      "status": "verified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Supported by excerpt E6."
    },
    {
      "text": "Cosmos Data Factory integrates tools and skills for labeling, curating, augmenting, and evaluating data at scale for training physical AI",
      "kind": "other",
      "status": "verified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Supported by excerpt E8."
    },
    {
      "text": "Cosmos Curator is a GPU-accelerated solution for curating video training datasets that now includes support for multimodal and multisensory inputs",
      "kind": "other",
      "status": "verified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Supported by excerpt E9."
    },
    {
      "text": "Cosmos Data Factory offers five cloud-native blueprints including Autonomous Vehicle Dataset Generation, Image Attribute Augmentation, Event Video Generation, Defect Image Generation, and Video Data Augmentation",
      "kind": "number",
      "status": "verified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Supported by excerpt E12."
    },
    {
      "text": "Developers can deploy core Cosmos models using updated NVIDIA Cosmos 3 NIM microservices which deliver up to 2x faster inference",
      "kind": "number",
      "status": "verified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Supported by excerpt E14."
    },
    {
      "text": "Porsche uses Cosmos Data Factory through Voxel51 on Microsoft Azure to reduce repeated physical test drives",
      "kind": "name",
      "status": "unverified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Excerpt E15 confirms Porsche uses Cosmos Data Factory through Voxel51 on Azure for an AV data flywheel, but does not state it reduces repeated physical test drives."
    },
    {
      "text": "ANYbotics generated over 1,500 synthetic video clips utilizing Cosmos Data Factory blueprints",
      "kind": "number",
      "status": "verified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Supported by excerpt E16."
    },
    {
      "text": "MicroAGI post-trained Cosmos 3 and distilled a 32-billion-parameter reasoner down to an 8-billion-parameter Nano model",
      "kind": "number",
      "status": "verified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Supported by excerpt E17."
    },
    {
      "text": "ADNOC utilizes Fogsphere's MistIQ agentic platform built with Cosmos and the NVIDIA Metropolis VSS Blueprint across 65 sites",
      "kind": "number",
      "status": "verified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Supported by excerpt E18."
    },
    {
      "text": "Cosmos Data Factory offers five cloud-native blueprints available through GitHub, Microsoft Azure, Nebius, and CoreWeave",
      "kind": "other",
      "status": "verified",
      "sourceUrl": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models",
      "note": "Supported by excerpt E21."
    }
  ]
}
